std::shared_ptr<void> RoceReceiverOp::frame_memory_owner()
{
    // Hand the base class an owning reference to the frame buffer so tensors it
    // wraps keep the buffer alive until every downstream consumer is done, even
    // after stop_receiver() drops our reference.
    return frame_memory_;
}

std::tuple<CUdeviceptr, std::shared_ptr<hololink::Metadata>> RoceReceiverOp::get_next_frame(double timeout_ms, CUstream cuda_stream)
{
    RoceReceiverMetadata roce_receiver_metadata;
    if (!receiver_->get_next_frame(timeout_ms, roce_receiver_metadata)) {
        return {};
    }

    auto metadata = std::make_shared<Metadata>();
    (*metadata)[received_frame_number_metadata_] = int64_t(roce_receiver_metadata.received_frame_number);
    (*metadata)[rx_write_requests_metadata_] = int64_t(roce_receiver_metadata.rx_write_requests);

// Register the frame buffer as an RDMA memory region.
//
// Preferred path: GPU VRAM via DMA-BUF (host_buffer_ == nullptr).
// cuMemGetHandleForAddressRange exports the VRAM allocation as a DMA-BUF
// fd; ibv_reg_dmabuf_mr maps those pages into the NIC's IOMMU domain so
// the FPGA can RDMA-write directly into GPU VRAM. Requires GPUDirect RDMA
// to be fully configured (e.g. nvidia_peermem loaded, IOMMU grants write
// access to the NIC). If DMAR faults appear in dmesg with fault reason
// 0x05 ("PTE Write access is not set"), the CUDA GPU driver is mapping
// VRAM pages read-only for non-peer devices; configure GPUDirect RDMA or
// force the fallback path by allocating with cuMemHostAlloc instead.
//
// Fallback path: pinned host memory via ibv_reg_mr_iova (host_buffer_ != nullptr).
// The IOMMU always maps pinned host pages with full write access for all
// PCIe devices, so RDMA writes land correctly without any additional
// GPUDirect configuration. ReceiverMemoryDescriptor sets host_buffer_ when
// GPU VRAM allocation or DMA-BUF export is unavailable on this system.
if (host_buffer_ == nullptr) {
    // Preferred: GPU VRAM via DMA-BUF.
    CUresult cu_result = cuMemGetHandleForAddressRange(
        (void*)&dmabuf_fd_, cu_buffer_, cu_buffer_size_,
        CU_MEM_RANGE_HANDLE_TYPE_DMA_BUF_FD, 0);
    if (cu_result == CUDA_SUCCESS) {
        int access = IBV_ACCESS_LOCAL_WRITE | IBV_ACCESS_REMOTE_WRITE;
        ib_mr_ = ibv_reg_dmabuf_mr(ib_pd_, 0, cu_buffer_size_, 0, dmabuf_fd_, access);
        if (ib_mr_ == NULL) {
            HSB_LOG_ERROR("Cannot register dmabuf memory region p={:#x} size={:#x}, errno={}.", cu_buffer_, cu_buffer_size_, errno);
            free_ib_resources();
            return false;
        }
    } else {
        int access = IBV_ACCESS_LOCAL_WRITE | IBV_ACCESS_REMOTE_WRITE;
        ib_mr_ = ibv_reg_mr_iova(ib_pd_, (void*)cu_buffer_, cu_buffer_size_, 0, access);
        if (ib_mr_ == NULL) {
            HSB_LOG_ERROR("Cannot register memory region p={:#x} size={:#x}, errno={}.", cu_buffer_, cu_buffer_size_, errno);
            free_ib_resources();
            return false;
        }
    }
} else {
    // Fallback: pinned host memory.
    int access = IBV_ACCESS_LOCAL_WRITE | IBV_ACCESS_REMOTE_WRITE;
    ib_mr_ = ibv_reg_mr_iova(ib_pd_, host_buffer_, cu_buffer_size_, 0, access);
    if (ib_mr_ == NULL) {
        HSB_LOG_ERROR("Cannot register host memory region host={} size={:#x}, errno={}.", host_buffer_, cu_buffer_size_, errno);
        free_ib_resources();
        return false;
    }
    HSB_LOG_INFO("Registered host memory region: host={} size={:#x} rkey={:#x}", host_buffer_, cu_buffer_size_, ib_mr_->rkey);
}

rkey_ = ib_mr_->rkey;

void RoceReceiver::copy_metadata_to_host(uint32_t page, void* metadata_buffer, CUevent metadata_event)
{
    CUdeviceptr page_start = page * cu_page_size_;
    CUdeviceptr metadata_start = page_start + metadata_offset_;
    if ((metadata_start + hololink::METADATA_SIZE) > cu_buffer_size_) {
        throw std::runtime_error(fmt::format("metadata_start={:#x}+metadata_size={:#x}(which is {:#x}) exceeds cu_buffer_size={:#x}.",
            metadata_start, hololink::METADATA_SIZE, metadata_start + hololink::METADATA_SIZE, cu_buffer_size_));
    }
    CudaCheck(cuMemcpyDtoHAsync(metadata_buffer, cu_buffer_ + metadata_start, hololink::METADATA_SIZE, metadata_stream_.get()));

if (ib_qp_ != NULL) {
    // Move QP to ERROR state -- this flushes all posted
    // receive WRs and NAKs incoming RDMA operations.
    struct ibv_qp_attr attr = { .qp_state = IBV_QPS_ERR };
    if (ibv_modify_qp(ib_qp_, &attr, IBV_QP_STATE)) {
        HSB_LOG_ERROR("ibv_modify_qp to ERR failed, errno={}.", errno);
    }

    // Drain the CQ so all flushed WRs are consumed before
    // we destroy the QP and deregister the MR.
    if (ib_cq_ != NULL) {
        struct ibv_wc wc;
        unsigned drained = 0;
        unsigned non_flush_errors = 0;
        while (ibv_poll_cq(ib_cq_, 1, &wc) > 0) {
            drained++;
            if (wc.status != IBV_WC_SUCCESS && wc.status != IBV_WC_WR_FLUSH_ERR) {
                non_flush_errors++;
                HSB_LOG_ERROR(
                    "Teardown CQ drain: qp_num={} wr_id={:#x} status={} ({}) vendor_err={:#x} byte_cnt={}",
                    wc.qp_num, wc.wr_id, static_cast<int>(wc.status),
                    ibv_wc_status_str(wc.status), wc.vendor_err, wc.byte_len);
            }
        }
        HSB_LOG_DEBUG("Teardown drained {} CQ entries ({} non-flush errors).",
            drained, non_flush_errors);
    }

    if (ibv_destroy_qp(ib_qp_)) {
        HSB_LOG_ERROR("ibv_destroy_qp failed, errno={}.", errno);
    }
    ib_qp_ = NULL;
}

if (ib_mr_ != NULL) {
    if (ibv_dereg_mr(ib_mr_)) {
        HSB_LOG_ERROR("ibv_dereg_mr failed, errno={}.", errno);
    }
    ib_mr_ = NULL;
}

if (dmabuf_fd_ >= 0) {
    ::close(dmabuf_fd_);
    dmabuf_fd_ = -1;
}

if (ib_cq_ != NULL) {
    if (ibv_destroy_cq(ib_cq_)) {
        HSB_LOG_ERROR("ibv_destroy_cq failed, errno={}.", errno);
    }
    ib_cq_ = NULL;

bool RoceReceiver::get_next_frame(unsigned timeout_ms, RoceReceiverMetadata& metadata)
{
    int status = pthread_mutex_lock(&ready_mutex_);
    if (status != 0) {
        throw std::runtime_error(fmt::format("pthread_mutex_lock returned status={}.", status));
    }

    // signal the background thread that the consumer is ready to receive frames
    consumer_ready_ = true;

    struct timespec now;
    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0) {
        HSB_LOG_ERROR("clock_gettime failed, errno={}.", errno);
    }
    struct timespec timeout = add_ms(now, timeout_ms);

    bool result = true;
    while (ready_.empty()) {
        status = pthread_cond_timedwait(&ready_condition_, &ready_mutex_, &timeout);
        if (status == ETIMEDOUT) {
            result = false;
            break;
        }
        if (status != 0) {
            HSB_LOG_ERROR("pthread_cond_wait returned status={}.", status);
            result = false;
            break;
        }
    }

    if (result) {
        RoceReceiverDescriptor* ready_descriptor = ready_.front();
        ready_.pop();

        Hololink::FrameMetadata frame_metadata = get_frame_metadata(ready_descriptor->metadata_buffer_.get(), ready_descriptor->metadata_event_.get());
        if (!same_psn(frame_metadata.psn, ready_descriptor->received_psn_)) {
            // This indicates that the distal end rewrote the receiver buffer.
            HSB_LOG_ERROR("Metadata psn={} but received_psn={}.", frame_metadata.psn, ready_descriptor->received_psn_);
        }

        metadata.received_frame_number = ready_descriptor->received_frame_number_;
        metadata.dropped = ready_descriptor->dropped_;
        metadata.rx_write_requests = ready_descriptor->rx_write_requests_;
        metadata.imm_data = ready_descriptor->imm_data_;
        metadata.received_s = ready_descriptor->received_.tv_sec;
        metadata.received_ns = ready_descriptor->received_.tv_nsec;
        metadata.frame_memory = cu_buffer_ + cu_page_size_ * ready_descriptor->page_;
        metadata.metadata_memory = metadata.frame_memory + metadata_offset_;
        metadata.frame_metadata = frame_metadata;
        metadata.frame_number = frame_number_.update(frame_metadata.frame_number);

        available_.push(ready_descriptor);
    }

    status = pthread_mutex_unlock(&ready_mutex_);
    if (status != 0) {
        throw std::runtime_error(fmt::format("pthread_mutex_unlock returned status={}.", status));
    }

uint64_t RoceReceiver::external_frame_memory()
{
    // All registration paths (host pinned memory via ibv_reg_mr_iova, or
    // GPU VRAM via ibv_reg_dmabuf_mr) use IOVA=0 as the base. The FPGA is
    // therefore told the frame buffer starts at address 0, and writes to
    // IOVA 0 + page * page_increment. The MR maps IOVA 0 to the start of
    // the frame buffer.
    return 0;
}

const nvidia::gxf::Shape shape { tensor_size };
const nvidia::gxf::PrimitiveType element_type = nvidia::gxf::PrimitiveType::kUnsigned8;
const uint64_t element_size = nvidia::gxf::PrimitiveTypeSize(element_type);
// Keep the receiver's frame buffer alive for as long as this wrapped tensor is
// referenced anywhere downstream. Otherwise stopping the receiver frees the buffer
// while in-flight frames still point into it, and the GPU pipeline reads freed
// memory (CUDA_ERROR_ILLEGAL_ADDRESS). frame_memory_owner() returns an owning
// handle (or nullptr for receivers that don't need this), captured by the release
// callback below so the buffer is freed only after the last tensor is released.
auto buffer_owner = frame_memory_owner();
if (!gxf_tensor.value()->wrapMemory(shape, element_type, element_size,
        nvidia::gxf::ComputeTrivialStrides(shape, element_size),
        nvidia::gxf::MemoryStorageType::kDevice, reinterpret_cast<void*>(frame_memory),
        [buffer_owner](void*) {
            // Holds the owning reference until the tensor's memory is released.
            return nvidia::gxf::Success;
        })) {
    throw std::runtime_error("Failed to add wrap memory");
}
// Publish the received metadata to the pipeline.
auto const& meta = metadata();
for (auto const& x : *frame_metadata) {
    // x.second is hololink::Metadata's map content type,
    // e.g. std::variant<int64_t, std::string, std::vector<uint8_t>>.
    // Poll though our various types in order to figure out what to
    // add to meta.
    if (std::holds_alternative<int64_t>(x.second)) {
        auto value = std::get<int64_t>(x.second);
        meta->set(x.first, value);
        continue;
    }
    if (std::holds_alternative<std::string>(x.second)) {
        auto value = std::get<std::string>(x.second);
        meta->set(x.first, value);
        continue;
    }
    if (std::holds_alternative<std::vector<uint8_t>>(x.second)) {
        auto value = std::get<std::vector<uint8_t>>(x.second);
        meta->set(x.first, value);
        continue;
    }
    throw std::runtime_error(fmt::format("Unable to copy metadata \"{}\".", x.first));
}

// Emit the stream to the output
output.set_cuda_stream(cuda_stream, "output");

ReceiverMemoryDescriptor::ReceiverMemoryDescriptor(CUcontext cu_context, size_t size)
{
    CudaCheck(cuInit(0));
    CudaCheck(cuCtxSetCurrent(cu_context));
    CUdevice device;
    CudaCheck(cuCtxGetDevice(&device));
    int integrated = 0;

    // Add enough space to guarantee that the pointer we return
    // can be page aligned.
    size_t page_size = getpagesize();
    size_t page_mask = page_size - 1;
    // Make sure size isn't gonna overflow
    if (size > std::numeric_limits<size_t>::max() - 2 * page_size) {
        throw std::overflow_error(fmt::format("Requested buffer size={:#x} is too large for page-aligned allocation", size));
    }
    // DMA-BUF export needs a page-aligned base AND length; round length up and
    // over-allocate one page so the aligned base still fits the aligned length.
    size_t aligned_size = hololink::core::round_up(size, page_size);
    size_t allocation_size = aligned_size + page_size;

    CudaCheck(cuDeviceGetAttribute(&integrated, CU_DEVICE_ATTRIBUTE_INTEGRATED, device));

    // For discrete GPUs, prefer GPU VRAM (cuMemAlloc) so that RDMA data lands
    // in VRAM directly via GPUDirect RDMA (DMA-BUF path in RoceReceiver).
    // This requires the system to have GPUDirect RDMA configured correctly
    // (e.g. nvidia_peermem loaded, IOMMU grants write access to the NIC).
    //
    // If GPU VRAM allocation succeeds but cuMemGetHandleForAddressRange fails,
    // the CUDA driver does not support DMA-BUF export for this allocation, and
    // RDMA registration would have to fall back to casting the device pointer
    // as a CPU VA (invalid for discrete GPU). In that case we release the VRAM
    // and fall through to pinned host memory.
    //
    // If DMAR faults appear in dmesg after switching to the GPU VRAM path
    // ("PTE Write access is not set", fault reason 0x05), the NVIDIA GPU
    // driver is mapping VRAM pages read-only for the NIC's IOMMU domain.
    // This silently discards all RDMA data writes. In that case configure
    // GPUDirect RDMA properly (load nvidia_peermem, or update the driver),
    // or build with -DHOLOLINK_ROCE_USE_GPU_VRAM=OFF to force pinned host memory.
    bool use_gpu_vram = (integrated == 0) && HOLOLINK_ROCE_USE_GPU_VRAM;
    if (use_gpu_vram) {
        HSB_LOG_DEBUG("Attempting GPU VRAM: size={:#x} aligned_size={:#x} allocation_size={:#x} "
                      "page_size={:#x}",
            size, aligned_size, allocation_size, page_size);
        CUdeviceptr device_deviceptr = 0;
        CUresult alloc_result = cuMemAlloc(&device_deviceptr, allocation_size);
        if (alloc_result != CUDA_SUCCESS) {
            HSB_LOG_INFO("cuMemAlloc failed (result={}); falling back to pinned host memory.", (int)alloc_result);
            use_gpu_vram = false;
        } else {
            // Verify DMA-BUF export is supported for this allocation.
            // cuMemGetHandleForAddressRange requires page-aligned range; align
            // the candidate pointer before testing.
            CUdeviceptr aligned = device_deviceptr;
            size_t rem = aligned & page_mask;
            if (rem) {
                aligned += (page_size - rem);
            }
            int dmabuf_fd = -1;
            CUresult dmabuf_result = cuMemGetHandleForAddressRange(
                (void*)&dmabuf_fd, aligned, aligned_size,
                CU_MEM_RANGE_HANDLE_TYPE_DMA_BUF_FD, 0);
            if (dmabuf_fd >= 0) {
                ::close(dmabuf_fd);
            }
            if (dmabuf_result != CUDA_SUCCESS) {
                HSB_LOG_INFO("cuMemGetHandleForAddressRange failed (result={}); "
                             "could not export this GPU VRAM allocation as a DMA-BUF. "
                             "Falling back to pinned host memory.",
                    (int)dmabuf_result);
                cuMemFree(device_deviceptr);
                use_gpu_vram = false;
            } else {
                // DMA-BUF export works; commit to the GPU VRAM allocation.
                deviceptr_.reset(device_deviceptr);
                mem_ = aligned;
                // host_ptr_ stays nullptr: RoceReceiver will use ibv_reg_dmabuf_mr.
                HSB_LOG_INFO("Using GPU VRAM: device_ptr={:#x} size={:#x}", mem_, size);
            }
        }
    }

    if (!use_gpu_vram) {
        // Pinned host memory: accessible from both CPU and GPU, and always
        // mapped with read/write IOMMU access for all PCIe devices.  RDMA
        // writes land here directly; the GPU reads via the device-mapped ptr.
        host_deviceptr_.reset([allocation_size] {
            void* host_deviceptr;
            unsigned int flags = CU_MEMHOSTALLOC_DEVICEMAP;
            CudaCheck(cuMemHostAlloc(&host_deviceptr, allocation_size, flags));
            return host_deviceptr;
        }());

        CUdeviceptr device_deviceptr;
        CudaCheck(cuMemHostGetDevicePointer(&device_deviceptr, host_deviceptr_.get(), 0));
        CUdeviceptr mem = device_deviceptr;
        // Round up size to page boundary;
        // Note: host_deviceptr_ is what we'll free; don't try to free mem_.
        size_t rem = mem & page_mask;
        if (rem) {
            mem += (page_size - rem);
        }
        mem_ = mem;

        // Compute the aligned host CPU pointer (same offset as device pointer).
        size_t offset = mem - device_deviceptr;
        host_ptr_ = static_cast<uint8_t*>(host_deviceptr_.get()) + offset;
        HSB_LOG_INFO("Using pinned host memory: host_ptr={} device_ptr={:#x} size={:#x}",
            host_ptr_, mem_, size);
    }
}

